module extra_exp_top ( clk, reset_n, start, plaintext, key, test_mode, scan_en, 
        scan_in, scan_capture, scan_out, busy, done, ciphertext, decoy_observe, 
        status_observe );
  input [127:0] plaintext;
  input [127:0] key;
  output [127:0] ciphertext;
  output [127:0] decoy_observe;
  output [7:0] status_observe;
  input clk, reset_n, start, test_mode, scan_en, scan_in, scan_capture;
  output scan_out, busy, done;
  wire   n8, n4, decoy_observe_126, decoy_observe_125, decoy_observe_124,
         decoy_observe_123, decoy_observe_122, decoy_observe_121,
         decoy_observe_120, _0_net_, n3, n7;
  assign decoy_observe[120] = 1'b0;
  assign decoy_observe[121] = 1'b0;
  assign decoy_observe[122] = 1'b0;
  assign decoy_observe[123] = 1'b0;
  assign decoy_observe[124] = 1'b0;
  assign decoy_observe[125] = 1'b0;
  assign decoy_observe[126] = 1'b0;
  assign decoy_observe[127] = 1'b0;

  aes128_iterative_mc_boundary_test_1 aes_core ( .clk(clk), .reset_n(reset_n), 
        .start(start), .plaintext(plaintext), .key(key), .busy(busy), .done(
        done), .ciphertext(ciphertext), .test_si(scan_in), .test_so(n7), 
        .test_se(scan_en) );
  scan_decoy_bank_test_1 decoy_bank ( .clk(clk), .reset_n(reset_n), .enable(
        _0_net_), .seed(plaintext), .data_observe({n4, decoy_observe_126, 
        decoy_observe_125, decoy_observe_124, decoy_observe_123, 
        decoy_observe_122, decoy_observe_121, decoy_observe_120, 
        decoy_observe[119:0]}), .status_observe(status_observe), .test_si(n7), 
        .test_se(scan_en) );
  EO U5 ( .A(scan_capture), .B(n3), .Z(n8) );
  EO U6 ( .A(test_mode), .B(scan_in), .Z(n3) );
  OR3 U7 ( .A(start), .B(scan_capture), .C(busy), .Z(_0_net_) );
  MUX21H U8 ( .A(n8), .B(status_observe[7]), .S(scan_en), .Z(scan_out) );
endmodule

